fn char_at(s: str, i: int) -> str =
    first(take(skip(chars(s), i), 1)) |> to_str

fn caesar(s: str, shift: int) -> str
    let lower = "abcdefghijklmnopqrstuvwxyz"
    let upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let m: map<str, str> = map<str, str>()
    let mut i = 0
    while i < 26
        let mut j = i + shift
        while j < 0
            j += 26
        while j >= 26
            j -= 26
        let orig_l = char_at(lower, i)
        let orig_u = char_at(upper, i)
        let shifted_l = char_at(lower, j)
        let shifted_u = char_at(upper, j)
        m.Add(orig_l, shifted_l)
        m.Add(orig_u, shifted_u)
        i += 1
    return s |> chars |> map(c => get(m, to_str(c), to_str(c))) |> join("")

